INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(5594, 'koKR', '%s zaczyna się wahać.', '', 0),
(7305, 'koKR', '', 'Nastały niebezpieczne czasy, $gposzukiwaczu:poszukiwaczko; przygód. Stąpaj ostrożnie.', 0),
(7306, 'koKR', 'Jestem $ggotów:gotowa; na iluzję, Myrando.', 'Jestem $ggotów:gotowa; na iluzję, Myrando.', 0),
(7449, 'koKR', '', 'Potrzebujesz iluzji?$B$BJeśli twoja iluzja osłabnie w trakcie zadania, wróć do mnie, a ponownie nałożę przebranie.$B$BJeśli poniesiesz porażkę, nie poddawaj się! Wróć do mnie. Będę ci pomagać, dopóki nie wypełnisz swoich zadań.', 0),
(7540, 'koKR', '', 'Dzięki, $n. A teraz wynośmy się stąd!', 0),
(7544, 'koKR', '', 'Udało się! Jeszcze raz dzięki! Pobiegnę przodem!', 0),
(7550, 'koKR', '', 'Hej, Hornizz! Wróciłam! A za mną idzie ktoś, kto pomógł mi wyjść z tarapatów.', 0),
(7551, 'koKR', '', 'Będziemy musieli skreślić Maraudine z naszej listy. Za trudno się z nimi współpracuje...', 0),
(7552, 'koKR', '', 'No, to ja idę do Gelkis. Nie są tak głupi jak Maraudine, ale za to rozsądniejsi.', 0),
(7553, 'koKR', 'Pa! Więcej szczęścia następnym razem!', '', 0),
(7554, 'koKR', 'Ta dziewczyna ciągle jest w biegu.', '', 0),
(7559, 'koKR', 'Hej, mon! $GNurkowałeś:Nurkowałaś; kiedyś głęboko w oceanie? Zdradzę ci mały sekret, co? Głęboko w oceanie znajdziesz musujące szczeliny; pozwolą ci oddychać powietrzem pod wodą. Ale zachowajmy ten sekret między nami, co? Nie potrzebuję konkurencji przy moich pułapkach na skorupiaki gdzie indziej... łapiesz, o co chodzi!\n', '', 0),
(7607, 'koKR', '', 'Powinnam znaleźć sobie kogoś do pomocy; nie lubię siedzieć tu cały dzień i sprzedawać sprzętu wędkarskiego. Wolałabym iść na ryby, a dopiero potem sprzedawać sprzęt.', 0),
(7614, 'koKR', 'Jestem Ulysses Rackmore, kapitan „Śmiałego”. A to dziennik z ostatnich kilku dni mojego skazanego na zagładę statku.$B$BPłynęliśmy do Warowni Lunopiórej z ładunkiem zaopatrzenia, gdy nagi przypuściły szturm na burty „Śmiałego”. Odparliśmy je, ale wiedzieliśmy, że wrócą. W obawie przed utratą moich najcenniejszych rzeczy skierowałem „Śmiałego” ku wyspie u wybrzeży Mrocznego Pustkowia, na której stoją stare ruiny nocnych elfów. I tam zostawiłem swoją skrzynię ze skarbem.', '', 0),
(7615, 'koKR', 'Czytaj dalej...', 'Czytaj dalej...', 0),
(7616, 'koKR', 'Moja skrzynia ma pomysłową konstrukcję i do otwarcia wymaga dwóch kluczy, złotego i srebrnego. Pierwszy klucz, srebrny, dałem pierwszemu oficerowi, a złoty zatrzymałem.$B$BAle było nam pisane je stracić. Mój klucz przepadł podczas kolejnego ataku nag, a klucz pierwszego oficera dzień później, gdy napadły nas suchokłape makrury i wciągnęły go w głębinę.$B$BJestem pewien, że klucze mają nagi i makrury. Dobrze, że są wrogami i nie podzielą się nimi.', '', 0),
(7617, 'koKR', 'Po ataku makrur widzieliśmy, że „Śmiały” nie przetrwa kolejnego. Opuściłem więc statek wraz z garstką ocalałych marynarzy.$B$BJesteśmy teraz na brzegu i wkrótce wyruszymy do Punktu Nijela, ale między nami a schronieniem czyha wiele niebezpieczeństw i obawiam się, że Mroczne Pustkowie nas pochłonie.$B$BPiszę to w nadziei, że ktoś pozna nasz los i pewnego dnia pomści nas na wodnych potworach, które nas zgubiły.', '', 0),
(7899, 'koKR', 'Jeśli chcesz polować na nagi, przyda ci się wszelka pomoc. Głęboko pod wodą znajdziesz musujące szczeliny, które wytwarzają tyle pęcherzyków powietrza, że da się oddychać pod wodą. Podpłyń blisko, by skorzystać z pęcherzyków.', '', 0),
(8324, 'koKR', 'Myrando, masz dość gałek ocznych, żeby zrobić kolejny amulet? $GZgubiłem:Zgubiłam; stary.', 'Myrando, masz dość gałek ocznych, żeby zrobić kolejny amulet? $GZgubiłem:Zgubiłam; stary.', 0),
(8918, 'koKR', 'Niech Cenarius cię prowadzi, $N.$B$BJestem w tej splugawionej krainie z moimi siostrami, z misją wielkiej wagi dla Kręgu Cenariona. Ale o takich sprawach rozmawiam tylko z tymi, którzy są dość potężni – wysłanie słabszej istoty byłoby szaleństwem.', '', 0),
(8919, 'koKR', '', 'Moje siostry i ja zeszłyśmy z Gór Szponogłazów, by zakończyć tragedię sprzed wieków. Niestety nie jesteśmy dość potężne, by same osiągnąć nasze cele, i teraz szukamy śmiertelników takich jak ty, by nam pomogli.$B$BJeśli jesteś $gdość potężny:dość potężna;, mamy wiele do omówienia, $N. Jeśli nie, dla twojego bezpieczeństwa pominę w naszej rozmowie szczegóły mojej misji.', 0),
(8920, 'koKR', '', '$n, proszę, obejrzyj próbkę pnącza Vylestem z jaskiń, żeby wiedzieć, czego szukać...', 0),
(8923, 'koKR', '$n, proszę, obejrzyj próbkę pnącza Vylestem z jaskiń, żeby wiedzieć, czego szukać...', '', 0),
(8925, 'koKR', 'Nareszcie jestem wolny od splugawienia, które niegdyś wiązało mnie z tym miejscem...', '', 0),
(8938, 'koKR', 'Opowiedz mi więcej o Maraudonie.', 'Opowiedz mi więcej o Maraudonie.', 0),
(8939, 'koKR', 'Dawno temu moje siostry driady i ja weszliśmy do tych jaskiń, by uwolnić udręczonego ducha mojego wuja, Zaetara. Jednak splugawienie, które już wtedy rozprzestrzeniło się po tych jaskiniach, wkrótce nas pokonało i my również upadliśmy.$B$BByło nam pisane błąkać się po tych korytarzach, z umysłami zatrutymi toksynami...$B$BChoć mój duch może teraz zaznać spokoju, wiem, że nie wypełniłem swojej misji. To wielki smutek, który muszę dźwigać...', '', 0),
(8940, 'koKR', 'Opowiedz mi więcej o Zaetarze.', 'Opowiedz mi więcej o Zaetarze.', 0),
(8941, 'koKR', 'Ach, Zaetar... <Celebras odwraca wzrok.>$B$BMój ojciec, Remulos, próbował go powstrzymać...$B$BZaetar był uparty, a gdy zakochał się w księżniczce żywiołu ziemi, mój ojciec wiedział, że ich związek jest przeklęty, ale Zaetar nie chciał słuchać.$B$BCentaury są skutkiem jego błędu. Urodziły się zniekształcone i pełne nienawiści; mojego wuja Zaetara zabili jego właśni krewni...$B$BZła księżniczka Theradras wciąż strzeże tu jego szczątków, w kryształowych jaskiniach.', '', 0),
(8947, 'koKR', 'Może spróbujemy tego później. Porozmawiaj ze mną ponownie, jeśli zechcesz.', '', 0),
(8948, 'koKR', 'Razem obie części znów staną się jednym.', '', 0),
(8949, 'koKR', 'Shal myrinan ishnu daldorah...', '', 0),
(8950, 'koKR', 'Przeczytaj księgę, którą przed tobą położyłem, i wypowiedz jej słowa na głos.', '', 0),
(8951, 'koKR', '%s zaczyna ukierunkowywać swoją energię, skupiając się na kamieniu.', '', 0),
(8952, 'koKR', 'Chcesz dowiedzieć się czegoś o kamieniu? Chodź za mną.', '', 0),
(8953, 'koKR', 'Tak długo błąkałem się w przeklętej postaci. $GUwolniłeś:Uwolniłaś; mnie... Twój trud zostanie wynagrodzony.', '', 0),
(8954, 'koKR', 'Proszę, rób, co mówię, $n.', '', 0),
(8955, 'koKR', 'Moje berło znów będzie całe!', '', 0),
(8961, 'koKR', 'Opowiedz mi więcej o historii Remulosa i Zaetara.', 'Opowiedz mi więcej o historii Remulosa i Zaetara.', 0),
(8962, 'koKR', 'Pytasz o synów Cenariusa, Remulosa i Zaetara.$B$BMój ojciec, Remulos, był silny i piękny, a mój wuj, Zaetar, bardzo przebiegły i drobnej postury. Choć darzono ich jednakowym szacunkiem, Zaetar zawsze czuł, że nie może się równać z chwałą i uwagą, jaką jego zdaniem cieszył się Remulos.$B$BGdy urodziłem się ja i moje siostry, Zaetar, zaślepiony zazdrością, postanowił prześcignąć brata... Sam sprowadził na siebie zgubę. Smutek, jaki mi to przynosi, nigdy nie zmalał, choć czas płynie...', '', 0),
(9032, 'koKR', '', 'To miejsce... jest przeklęte.$B$BLedwo udało mi się uciec i nie zniosę kolejnego zejścia do tych tuneli.$B$BAle mój brat i siostry... Oni nie mieli tyle szczęścia. Są uwięzieni w środku, a trawi ich gorączka od splugawionych oparów, które unoszą się ze złego ogrodu rosnącego w głębi.$B$BProszę, musisz pomóc.', 0);
